"""Module dependency graph and root scoped compilation order."""

from collections import defaultdict
from heapq import heapify, heappop, heappush
from typing import List


class DependencyGraph:
    """Directed graph of compilation prerequisites.

    ``add_edge(a, b)`` records that ``a`` must be compiled before ``b``; in
    campaign terms ``a`` is a call callee or a pipe filter and ``b`` is its
    caller/target.  Duplicate edges have no extra effect.
    """

    def __init__(self):
        self.graph = defaultdict(set)
        self.dependencies = defaultdict(set)
        self.filter_functions = []
        self.model_to_node = {}
        self.node_to_model = {}
        self.nodes = 0
        self.oracle = None

    def add_node(self, model):
        if model in self.model_to_node:
            return self.model_to_node[model]
        index = self.nodes
        self.model_to_node[model] = index
        self.node_to_model[index] = model
        self.nodes += 1
        return index

    def add_edge(self, model1, model2):
        """Record that ``model1`` is a prerequisite of ``model2``."""
        self.add_node(model1)
        self.add_node(model2)
        self.graph[model1].add(model2)
        self.dependencies[model2].add(model1)

    def Edge(self, model1, model2):
        # adds a directed edge from model1 to model2
        self.add_edge(model1, model2)

    def CallEdge(self, model, dependency_models: List):
        # adds edges from dependency_models to model
        for dep_model in dependency_models:
            self.add_edge(dep_model, model)

    def Pipe(self, model1, model2):
        # adds a pipe from model2 to model1
        self.filter_functions.append(model2)
        self.add_edge(model2, model1)

    def Node(self, model):
        # creates a new node in the dependency graph
        self.add_node(model)

    def prerequisites(self, model):
        return self.dependencies[model]

    def closure(self, root):
        """Every transitive prerequisite of ``root``, including ``root``."""
        seen = {root}
        stack = [root]
        while stack:
            current = stack.pop()
            for prerequisite in self.dependencies[current]:
                if prerequisite not in seen:
                    seen.add(prerequisite)
                    stack.append(prerequisite)
        return seen

    def topologicalSortUtil(self, v, visited, sorted_order):
        visited[v] = True
        for i in self.graph[v]:
            if not visited[i]:
                self.topologicalSortUtil(i, visited, sorted_order)
        sorted_order.append(v)

    def topologicalSort(self):
        sorted_order = []
        visited = {model: False for model in self.model_to_node}
        for model in list(self.model_to_node):
            if not visited[model]:
                self.topologicalSortUtil(model, visited, sorted_order)
        sorted_order.reverse()
        return sorted_order

    def compile_order(self, root):
        """Root scoped compilation order.

        Returns the root plus every transitive call/pipe prerequisite, ordered
        so prerequisites precede their dependents, choosing the
        lexicographically smallest eligible name at every step.  Unrelated
        modules and filters are absent.
        """
        scope = self.closure(root)
        pending = {model: len(self.dependencies[model] & scope) for model in scope}
        ready = [model for model, count in pending.items() if count == 0]
        heapify(ready)
        order = []
        while ready:
            model = heappop(ready)
            order.append(model)
            for dependent in self.graph[model]:
                if dependent in scope:
                    pending[dependent] -= 1
                    if pending[dependent] == 0:
                        heappush(ready, dependent)
        if len(order) != len(scope):
            raise ValueError('dependency cycle involving ' + str(root))
        return order
