"""Corpus identity: a record is its entry plus its recovered input values.

Model results, raw bytes after a string NUL, transport arguments, object order
and preparation metadata are witnesses or transport details, never identity.
JSON type identity is preserved: booleans are not integers, empty arrays are
not empty objects.
"""

__all__ = ['make_hashable', 'recreate_structure', 'corpus_key', 'Corpus']

_NONE = (0,)
_BOOL = (1,)
_INT = (2,)
_STR = (3,)
_LIST = (4,)
_DICT = (5,)
_FLOAT = (6,)


def make_hashable(obj):
    """A type tagged, hashable canonical form of a recovered JSON value."""
    if obj is None:
        return _NONE
    if obj is True:
        return (_BOOL, 1)
    if obj is False:
        return (_BOOL, 0)
    if isinstance(obj, int):
        return (_INT, obj)
    if isinstance(obj, str):
        return (_STR, obj)
    if isinstance(obj, float):
        return (_FLOAT, obj)
    if isinstance(obj, (list, tuple)):
        return (_LIST, tuple(make_hashable(item) for item in obj))
    if isinstance(obj, dict):
        return (_DICT, tuple(sorted((key, make_hashable(value))
                                    for key, value in obj.items())))
    raise TypeError(f'cannot canonicalise {type(obj).__name__}')


def recreate_structure(hashable):
    """Rebuild a JSON value from its canonical hashable form."""
    if isinstance(hashable, tuple) and hashable:
        tag = hashable[0]
        if tag is _NONE or tag == 0:
            return None
        if tag is _BOOL or tag == 1:
            return bool(hashable[1])
        if tag is _INT or tag == 2:
            return hashable[1]
        if tag is _STR or tag == 3:
            return hashable[1]
        if tag is _FLOAT or tag == 6:
            return hashable[1]
        if tag is _LIST or tag == 4:
            return [recreate_structure(item) for item in hashable[1]]
        if tag is _DICT or tag == 5:
            return {key: recreate_structure(value) for key, value in hashable[1]}
    if isinstance(hashable, tuple):
        return tuple(recreate_structure(item) for item in hashable)
    return hashable


def corpus_key(entry, inputs):
    """The corpus identity of one recovered record."""
    return (entry, make_hashable(inputs))


class Corpus(object):
    """Canonical corpus assembly with first-usable-run index assignment."""

    __slots__ = ('rows', 'index')

    def __init__(self):
        self.rows = []
        self.index = {}

    def intern(self, key, entry, inputs, cost, commands, witness):
        """Record a usable witness; returns ``(case_index, is_new)``."""
        position = self.index.get(key)
        if position is None:
            position = len(self.rows)
            self.index[key] = position
            self.rows.append({
                'entry': entry,
                'inputs': inputs,
                'cost': cost,
                'commands': list(commands),
                'witnesses': [witness],
            })
            return position, True
        self.rows[position]['witnesses'].append(witness)
        return position, False

    def __len__(self):
        return len(self.rows)
